// Import of required libraries
import { test, expect, SkyrampClient, getBaseUrl, getValue, getResponseValue } from '@skyramp/skyramp';
import { createLink, getLinksList, deleteLink, deleteCollection } from './skyrampUtils';

// URL for test requests
const URL_localhost = getBaseUrl("SKYRAMP_TEST_BASE_URL", "http://localhost:3000");

test('testIntegration', async () => {
    test.setTimeout(60000);

    // Invocation of Skyramp Client
    const client = new SkyrampClient();
    // Definition of authentication header
    const headers: Record<string, string> = {};
    if (process.env.SKYRAMP_TEST_TOKEN && process.env.SKYRAMP_TEST_TOKEN != "") {
        headers["Authorization"] = "Bearer " + process.env.SKYRAMP_TEST_TOKEN;
    }

    // Request Body
    const linksPostRequestBody: string = `{
        "collection": {
            "name": "testbot-archive-status-list-col"
        },
        "name": "testbot-archive-status-list",
        "tags": [],
        "url": "http://127.0.0.1:9/testbot-archive-status-list"
    }`;

    const linksPostResponse = await createLink(client, URL_localhost, headers, linksPostRequestBody);
    expect(linksPostResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksPostResponse, "response.name"), 'name').toBe("testbot-archive-status-list");
    expect(getResponseValue(linksPostResponse, "response.url"), 'url').toBe("http://127.0.0.1:9/testbot-archive-status-list");
    expect(getResponseValue(linksPostResponse, "response.type"), 'type').toBe("url");
    expect(getResponseValue(linksPostResponse, "response.collection.name"), 'collection name').toBe("testbot-archive-status-list-col");
    expect(getResponseValue(linksPostResponse, "response.id"), 'id').toBeGreaterThan(0);
    expect(getResponseValue(linksPostResponse, "response.collection.id"), 'collection id').toBeGreaterThan(0);
    expect(Date.parse(String(getResponseValue(linksPostResponse, "response.lastPreserved"))), 'lastPreserved parses as a time').not.toBeNaN();
    expect(getResponseValue(linksPostResponse, "response.pdf"), 'pdf').toBe("unavailable");
    expect(getResponseValue(linksPostResponse, "response.monolith"), 'monolith').toBe("unavailable");
    expect(getResponseValue(linksPostResponse, "response.readable"), 'readable').toBe("unavailable");

    const linksGetResponse = await getLinksList(client, URL_localhost, headers, {"sort": ["0"]});
    expect(linksGetResponse.statusCode, 'status code').toBe(200);

    const listedLinks = getResponseValue(linksGetResponse, "response") as any[];
    expect(Array.isArray(listedLinks), 'response is a list').toBe(true);
    expect(listedLinks.length, 'list holds at least the link this test created').toBeGreaterThanOrEqual(1);
    const listedCreatedLink = listedLinks.find((link) => link.id === getResponseValue(linksPostResponse, "response.id"));
    expect(listedCreatedLink, 'the created link appears in the list').toBeDefined();
    expect(listedCreatedLink.name, 'name').toBe("testbot-archive-status-list");
    expect(listedCreatedLink.url, 'url').toBe("http://127.0.0.1:9/testbot-archive-status-list");
    expect(listedCreatedLink.collectionId, 'collectionId').toBe(getResponseValue(linksPostResponse, "response.collection.id"));
    expect(Date.parse(String(listedCreatedLink.lastPreserved)), 'lastPreserved parses as a time').not.toBeNaN();
    expect(listedCreatedLink.archiveStatus, 'archiveStatus of a link whose preservation has finished').toBe("completed");

    const linksLinksDeleteResponse = await deleteLink(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.id"));
    expect(linksLinksDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(linksLinksDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.id"));
    expect(getResponseValue(linksLinksDeleteResponse, "response.name"), 'name').toBe("testbot-archive-status-list");

    const collectionsDeleteResponse = await deleteCollection(client, URL_localhost, headers, getResponseValue(linksPostResponse, "response.collection.id"));
    expect(collectionsDeleteResponse.statusCode, 'status code').toBe(200);

    expect(getResponseValue(collectionsDeleteResponse, "response.id"), 'id').toBe(getResponseValue(linksPostResponse, "response.collection.id"));
    expect(getResponseValue(collectionsDeleteResponse, "response.name"), 'collection name').toBe("testbot-archive-status-list-col");
});
